use napi::{Error,Result};use napi_derive::napi;const MAX_SOURCE:usize=8388608;const MAX_DIMS:usize=16384;const MAX_CANDIDATES:usize=10000;const MAX_VALUES:usize=1000000;fn err(s:&str)->Error{Error::from_reason(s.to_owned())}fn norm(v:&[f64])->Result<f64>{if v.is_empty()||v.len()>MAX_DIMS{return Err(err("Embedding dimensions must be between 1 and 16384."));}if v.iter().any(|x|!x.is_finite()){return Err(err("Embedding values must be finite."));}let n=v.iter().map(|x|x*x).sum::<f64>().sqrt();if !n.is_finite()||n<=f64::EPSILON{return Err(err("Embedding vector must have non-zero magnitude."));}Ok(n)}
#[napi(object)]pub struct EngineInfo{pub engine:String,pub version:String,pub node_api_version:u32,pub capabilities:Vec<String>}#[napi(object)]pub struct SourceStats{pub bytes:u32,pub lines:u32,pub token_count:u32}#[napi(object)]pub struct RankedEmbedding{pub index:u32,pub score:f64}
#[napi(js_name="engineInfo")]pub fn engine_info()->EngineInfo{EngineInfo{engine:"Brightdesk Rust Native Engine".into(),version:env!("CARGO_PKG_VERSION").into(),node_api_version:8,capabilities:vec!["source-chunking".into(),"source-analysis".into(),"embedding-normalization".into(),"cosine-similarity".into(),"vector-ranking".into(),"provider-neutral".into()]}}
#[napi(js_name="normalizeEmbedding")]pub fn normalize_embedding(v:Vec<f64>)->Result<Vec<f64>>{let n=norm(&v)?;Ok(v.into_iter().map(|x|x/n).collect())}fn cosine(a:&[f64],b:&[f64])->Result<f64>{let x=norm(a)?;let y=norm(b)?;if a.len()!=b.len(){return Err(err("Embedding dimensions must match."));}Ok((a.iter().zip(b).map(|(p,q)|p*q).sum::<f64>()/(x*y)).clamp(-1.0,1.0))}
#[napi(js_name="cosineSimilarity")]pub fn cosine_similarity(a:Vec<f64>,b:Vec<f64>)->Result<f64>{cosine(&a,&b)}
#[napi(js_name="rankEmbeddings")]pub fn rank_embeddings(q:Vec<f64>,c:Vec<Vec<f64>>,l:Option<u32>)->Result<Vec<RankedEmbedding>>{let _=norm(&q)?;if c.len()>MAX_CANDIDATES||c.iter().map(Vec::len).sum::<usize>()+q.len()>MAX_VALUES{return Err(err("Ranking request exceeds configured limits."));}let mut r=Vec::new();for(i,v)in c.iter().enumerate(){r.push(RankedEmbedding{index:i as u32,score:cosine(&q,v)?});}r.sort_by(|a,b|b.score.total_cmp(&a.score).then_with(||a.index.cmp(&b.index)));r.truncate(l.unwrap_or(r.len()as u32).min(r.len()as u32)as usize);Ok(r)}
#[napi(js_name="chunkSource")]pub fn chunk_source(s:String,m:Option<u32>)->Result<Vec<String>>{if s.len()>MAX_SOURCE{return Err(err("Source text exceeds 8 MiB."));}let max=m.unwrap_or(2400)as usize;if !(128..=16000).contains(&max){return Err(err("Chunk size must be between 128 and 16000 bytes."));}let mut o=Vec::new();let mut st=0;while st<s.len(){let t=(st+max).min(s.len());let mut e=t;while e>st&&!s.is_char_boundary(e){e-=1;}if e<s.len(){if let Some(n)=s[st..e].rfind('\n'){let p=st+n+1;if p>st+max/2{e=p;}}}if e==st{e=s[st..].char_indices().nth(1).map(|(i,_)|st+i).unwrap_or(s.len());}o.push(s[st..e].into());st=e;}Ok(o)}
#[napi(js_name="analyzeSource")]pub fn analyze_source(s:String)->Result<SourceStats>{if s.len()>MAX_SOURCE{return Err(err("Source text exceeds 8 MiB."));}Ok(SourceStats{bytes:s.len()as u32,lines:s.lines().count()as u32,token_count:s.split_whitespace().count()as u32})}
#[cfg(test)]mod tests{use super::*;#[test]fn vector_tests(){let v=normalize_embedding(vec![3.0,4.0]).unwrap();assert!((v[0]-0.6).abs()<1e-10);assert!(normalize_embedding(vec![0.0]).is_err());assert!(normalize_embedding(vec![f64::NAN]).is_err());}#[test]fn ranking(){let r=rank_embeddings(vec![1.0,0.0],vec![vec![0.0,1.0],vec![1.0,0.0],vec![2.0,0.0]],None).unwrap();assert_eq!(r.iter().map(|x|x.index).collect::<Vec<_>>(),vec![1,2,0]);}#[test]fn unicode(){let s="🦀".repeat(100);let c=chunk_source(s.clone(),Some(128)).unwrap();assert!(c.iter().all(|x|x.len()<=128));assert_eq!(c.concat(),s);}}